from author import put

def F(id,hc,ha,bc,ba):put('service1',id,{'caption':hc,'alt':ha},{'caption':bc,'alt':ba})
def N(n,*a):F(f'rst31-service1-fig{n:03}',*a)
N(1,'लगभग15° हल्का,30° आदरपूर्ण और45° गहरा झुकना तुलना करें। केवल गर्दन न मोड़ें; पीठ सीधी रखें।','बगल से तीन झुकाव; कमर से सीधे ऊपरी शरीर का कोण।','প্রায়15° হালকা,30° সম্মান ও45° গভীর ঝোঁকা তুলনা; শুধু ঘাড় নয়, পিঠ সোজা।','পাশ থেকে তিন নত হওয়া; কোমর থেকে সোজা ওপরের দেহের ঢাল।')
N(2,'मुख्य हाथ के विपरीत हाथ से केंद्र सँभालें। भारी चीज शरीर की ओर से रखें और उँगलियों की ओर से उतारें।','ऊपर से ट्रे के नीचे दिखती हथेली-फैली उँगलियाँ; शरीर की ओर भारी प्लेट और सिरे पर छोटी प्लेट।','প্রধান হাতের বিপরীত হাতে কেন্দ্র ধরুন; ভারী জিনিস শরীরের দিক থেকে রাখুন, আঙুলের দিক থেকে নামান।','ওপর থেকে ট্রের নিচের হাত-ছড়ানো আঙুল, শরীরদিকে ভারী ও আঙুলদিকে ছোট প্লেট।')
N(3,'गिलास के नीचे और प्लेट के तल को सहारा दें; पीने के किनारे या भोजन को उँगली न छुए।','गिलास के नीचे के आधे भाग और प्लेट के किनारे-तल पकड़ने के दो चित्र।','গ্লাসের নিচ ও প্লেটের তলা ধরুন; পান করার মুখ বা খাবার আঙুলে নয়।','গ্লাসের নিচের অর্ধেক ও প্লেটের ধার-তলা ধরার দুই চিত্র।')
N(4,'उल्टे V (ऊपर पास, नीचे खुले) आकार और तिरछे साथ रखे कटलरी तुलना करें; हटाने से पहले प्रगति और इच्छा पूछें।','दो प्लेटों पर उल्टा V (ऊपर पास, नीचे खुला) और साथ तिरछे रखे औजार।','উল্টো V (ওপরে কাছে, নিচে খোলা) ও তির্যক পাশাপাশি কাটলারি তুলনা; সরানোর আগে খাওয়ার অবস্থা-ইচ্ছা দেখুন।','দুই প্লেটে উল্টো V (ওপরে কাছে, নিচে খোলা) ও তির্যক পাশাপাশি সরঞ্জাম।')
N(5,'जापानी कक्ष और गोल मेज का उदाहरण; प्रवेश-आला देखकर इच्छा और चलने की शर्त पूछें।','प्रवेश, सजावटी आला, मेज और सीट का कक्ष व गोल मेज का नक्शा।','জাপানি ঘর-গোল টেবিলের উদাহরণ; প্রবেশ-কুঠুরি দেখে ইচ্ছা ও চলাচল জানুন।','প্রবেশ, কুঠুরি, টেবিল-আসনের ঘর ও গোল টেবিলের নকশা।')
N(6,'सहायक वाली और बड़े पहिए पर हाथ की रिंग वाली स्वयं चलने वाली कुर्सी; प्रकार से सहायता न तय करें।','बगल से दोनों व्हीलचेयर; स्वयं चलने वाले की हैंड रिंग दिखाई है।','সহায়কচালিত ও বড় চাকায় হাতের রিংযুক্ত স্বচালিত; ধরনেই সহায়তা নয়।','পাশ থেকে দুই হুইলচেয়ার ও স্বচালিতের হাতের রিং।')
N(7,'नीची चॉपस्टिक स्थिर और ऊपरी चलती है; हाथ स्थिति समझाने का संकेत है।','हाथ और दो चॉपस्टिक; नीचे स्थिर, ऊपर खुलने का स्थान बिंदी से।','নিচের চপস্টিক স্থির ও ওপরেরটি চলে; হাত অবস্থান বোঝানোর প্রতীক।','হাত-দুই চপস্টিক; নিচ স্থির, ওপর খোলার স্থান বিন্দুতে।')
N(8,'नरम आँख और ऊपर उठे होठ के कोने देखें; सामने वाले का अनुभव पूछकर अभ्यास करें।','शांत आँख और मुँह के कोने वाला चेहरा; आँख-मुँह पर रेखाएँ।','কোমল চোখ ও উঁচু ঠোঁটের কোণ দেখুন; অপরের অনুভূতি জেনে অনুশীলন।','শান্ত চোখ-মুখের কোণের মুখচিত্রে নির্দেশরেখা।')
notes=[('10000-o','10,000','आगे','शिबुसावा एइइचि','সামনে','শিবুসাওয়া এইইচি'),('10000-r','10,000','पीछे','टोक्यो स्टेशन का मारुनोउचि भवन','পেছনে','টোকিও স্টেশনের মারুনোউচি ভবন'),('5000-o','5,000','आगे','त्सुदा उमेको','সামনে','তসুদা উমেকো'),('5000-r','5,000','पीछे','विस्टेरिया फूल','পেছনে','উইস্টেরিয়া ফুল'),('1000-o','1,000','आगे','कितासातो शिबासाबुरो','সামনে','কিতাসাতো শিবাসাবুরো'),('1000-r','1,000','पीछे','फूजी के36दृश्यों का कानागावा की विशाल लहर चित्र','পেছনে','ফুজির36দৃশ্যের কানাগাওয়ার বিশাল ঢেউ')]
