for amount in [10000,5000,1000]:
 for suffix,hs,bs in [('11','आगे','সামনে'),('12','पीछे','পেছনে')]:
  h=f'2004 से जारी पुराने रूप के नोट का {hs} आधिकारिक नमूना। राशि और चित्र जाँचें। स्रोत: वित्त मंत्रालय।';b=f'2004 থেকে জারি পুরোনো নোটের {bs}র সরকারি নমুনা। মূল্য ও ছবি দেখুন। উৎস: অর্থ মন্ত্রণালয়।';F(f'rst31-service1-mof-2004-{amount}-{suffix}',h,h,b,b)
for suffix,hs,bs in [('o','आगे','সামনে'),('r','पीछे','পেছনে')]:
 F('rst31-service1-mof-2000-2000-'+suffix,f'2000 से जारी2000येन नोट का {hs}। स्रोत: वित्त मंत्रालय।',f'2000 से जारी2000येन के {hs} का नमूना।',f'2000 থেকে জারি2000ইয়েন নোটের {bs}। উৎস: অর্থ মন্ত্রণালয়।',f'2000 থেকে জারি2000ইয়েনের {bs}র নমুনা।')
 F('rst31-service1-mof-coin-500-old-'+suffix,f'2000–2021 में जारी500येन का {hs} भाग। अभी चलने वाले चित्र का उदाहरण। स्रोत: वित्त मंत्रालय।',f'पुराने500येन निकेल-पीतल सिक्के के {hs} का आधिकारिक चित्र।',f'2000–2021-এ জারি500ইয়েনের {bs}। এখনও বৈধ নকশার উদাহরণ। উৎস: অর্থ মন্ত্রণালয়।',f'পুরোনো500ইয়েন নিকেল-পিতল মুদ্রার {bs}র সরকারি ছবি।')
F('rst31-service1-official-ostomate','ओस्टोमेट सुविधा का मार्गदर्शक चिह्न। स्रोत: कैबिनेट कार्यालय।','ओस्टोमेट सुविधा का आधिकारिक मार्गदर्शक चिह्न।','অস্টোমেট সুবিধার নির্দেশচিহ্ন। উৎস: ক্যাবিনেট অফিস।','অস্টোমেট সুবিধার সরকারি নির্দেশচিহ্ন।')
N(9,'प्रभावी खाँसी हो तो जारी रखें और निगरानी करें। आवाज न निकले या खाँसी कमजोर हो तो दम घुटना मानकर तुरंत119और मदद बुलाएँ।','बाएँ खाँसता और दाएँ गला पकड़े व्यक्ति तथा119फोन।','ভালো কাশিতে কাশতে দিয়ে দেখুন; স্বর নেই বা দুর্বল কাশিতে শ্বাসরোধ সন্দেহে সঙ্গে সঙ্গে119ও সাহায্য।','বাঁয়ে কাশি, ডানে গলা ধরা ব্যক্তি ও119ফোন।')
N(10,'वयस्क की पीठ की दोनों कंधे-हड्डियों के बीच और हथेली का आधार दिखता है। पेट के धक्के के अपवाद हैं; शिशु की विधि अलग। आधिकारिक प्रशिक्षण वीडियो से मुद्रा-क्रम देखें।','वयस्क की पीठ में कंधे की हड्डियाँ व बीच का स्थान और हाथ में हथेली का आधार दिखाता सैद्धांतिक चित्र।','প্রাপ্তবয়স্কের দুই কাঁধের হাড়ের মাঝ ও হাতের গোড়া দেখানো। পেটের ধাক্কায় বাদ পড়া শর্ত আছে; শিশুর পদ্ধতি আলাদা। সরকারি প্রশিক্ষণ ভিডিওতে ভঙ্গি-ধাপ দেখুন।','প্রাপ্তবয়স্কের পিঠে দুই কাঁধের হাড়-মাঝ এবং হাতে গোড়ার তাত্ত্বিক অবস্থানচিত্র।')
F('rst31-cs2-fig-emergency-roles-on-rst-1-svc-19','119,AED,प्रवेश मार्गदर्शन और सुरक्षा बाँटें। केवल फोन,AEDऔर मार्गदर्शन की भूमिका; तकनीक या पैड की जगह नहीं सिखाता।','अचानक स्वास्थ्य बिगड़ने में कॉल,AEDऔर मार्गदर्शन की भूमिका।','119,AED,প্রবেশে পথ ও চারপাশ নিরাপত্তা ভাগ। শুধু ফোন,AEDআনা ও পথের ভূমিকা, কৌশল বা প্যাডের স্থান নয়।','হঠাৎ অসুস্থতায় ফোন,AEDও পথ দেখানোর ভূমিকা।')
